function nearest(a, codebook) {
  var best = 0, bs = Infinity;
  for (var k = 0; k < codebook.length; k++) {
    var b = codebook[k], nb = 0, dot = 0;
    for (var i = 0; i < a.length; i++) { nb += b[i] * b[i]; dot += a[i] * b[i]; }
    var score = nb - 2 * dot;
    if (score < bs) { bs = score; best = k; }
  }
  return best;
}

